CREATE TABLE public.campaign_gm_states (campaign_id bigint NOT NULL, updated_by uuid NOT NULL, secret_state text DEFAULT ''::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
ALTER TABLE public.campaign_gm_states ENABLE ROW LEVEL SECURITY;
