CREATE POLICY campaign_gm_states_update_managers ON public.campaign_gm_states FOR UPDATE TO authenticated USING (( SELECT private.is_campaign_manager(campaign_gm_states.campaign_id) AS is_campaign_manager)) WITH CHECK (((updated_by = ( SELECT auth.uid() AS uid)) AND ( SELECT private.is_campaign_manager(campaign_gm_states.campaign_id) AS is_campaign_manager)));
