CREATE POLICY campaign_objectives_select_allowed ON public.campaign_objectives FOR SELECT TO authenticated USING ((( SELECT private.is_campaign_member(campaign_objectives.campaign_id) AS is_campaign_member) AND ((NOT is_secret) OR ( SELECT private.is_campaign_manager(campaign_objectives.campaign_id) AS is_campaign_manager))));
CREATE POLICY campaign_objectives_update_managers ON public.campaign_objectives FOR UPDATE TO authenticated USING (( SELECT private.is_campaign_manager(campaign_objectives.campaign_id) AS is_campaign_manager)) WITH CHECK (( SELECT private.is_campaign_manager(campaign_objectives.campaign_id) AS is_campaign_manager));
